def drive(me, enemy, arena):
    # Keep the enemy roughly at our side (±90°) and move forward.
    bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive = left
    # If we are facing roughly head‑on, turn to the left side.
    if abs(bearing) < 30:
        return (0.4, -0.4)  # turn left in place
    # If we are already on a side, drive forward.
    if 30 <= bearing <= 150:
        # Enemy is on our left side → keep turning left a bit to stay there
        return (0.6, 0.6)
    if -150 <= bearing <= -30:
        # Enemy is on our right side
        return (0.6, 0.6)
    # If enemy is behind, turn away to avoid being hit from the front.
    if bearing > 150:
        return (-0.4, 0.4)   # turn right
    else:
        return (0.4, -0.4)   # turn left

