    if r > 4.0:
        w = (r - 4.0) / 1.5
        if w > 2.0:
            w = 2.0
    tx = enemy.x - w * me.x
    ty = enemy.y - w * me.y
    if abs(tx - me.x) < 0.01 and abs(ty - me.y) < 0.01:
        tx = 0.0
        ty = 0.0
    b = bearing_to(tx, ty)
    turn = b / 30.0
